import { expect, test } from "bun:test";

import { evaluateGate, gateTally, normalizeGateNames } from "../src/gate.ts";

test("all checks evidenced pass", () => {
  expect(
    evaluateGate({
      checks: [
        { name: "lint", passed: true, evidenced: true },
        { name: "test", passed: true, evidenced: true },
      ],
    }),
  ).toEqual({ verdict: "pass", failed: [], unevidenced: [] });
});

test("a failed check fails the gate", () => {
  expect(
    evaluateGate({
      checks: [
        { name: "lint", passed: true, evidenced: true },
        { name: "test", passed: false, evidenced: true },
      ],
    }),
  ).toEqual({ verdict: "fail", failed: ["test"], unevidenced: [] });
});

test("tally counts verdicts", () => {
  expect(gateTally([{ verdict: "pass" }, { verdict: "fail" }, { verdict: "pass" }])).toEqual({
    pass: 2,
    fail: 1,
  });
});

test("normalize dedupes", () => {
  expect(normalizeGateNames(["z-gate", "a-gate", "z-gate"])).toEqual(["a-gate", "z-gate"]);
});
